// #662546 — экран /admin/tenders и детали /admin/tenders/<id> (platform admin). ТОЛЬКО ЧТЕНИЕ; «ניסיון חוזר» не нажимается.
// Кейсы: .qa/tests/admin-tenders/ADT-01..ADT-06. План: .qa/e2e/specs/admin-tenders.md.
// ВНИМАНИЕ: вход platform один (ротация токена) — файл идёт строго по порядку (serial) в ОДНОМ окне; запускать с --workers=1
// и не параллелить с другими тестами роли platform (admin-companies-users, mobile-tables/admin-mobile, admin-tenders-mobile).
// Не зависит от строк в сбое (QA-T2/QA-T3 могут быть «ממתין»): «לטיפול» — пропуск с сообщением, если сбойных строк нет.
import { test, expect, Page, BrowserContext } from '@playwright/test';
import { openRoleContext } from '../admin-companies-users/helpers';
import { OK_TENDER, openTenders, tendersRows, tendersSearch, stateFilter, detailsLink, expectDetailsPage } from './helpers';

test.describe.configure({ mode: 'serial' });

let ctx: BrowserContext;
let page: Page;
const mutations: string[] = [];

test.beforeAll(async ({ browser }, testInfo) => {
  ctx = await openRoleContext(browser, testInfo, 'platform');
  page = await ctx.newPage();
  page.on('request', (r) => {
    if (['GET', 'HEAD', 'OPTIONS'].includes(r.method())) return;
    if (!/supabase\.co/.test(r.url()) || /\/auth\/v1\//.test(r.url())) return;
    mutations.push(`${r.method()} ${r.url()}`);
  });
});
test.afterAll(async () => {
  await ctx?.close();
});

test.describe('ניהול מכרזים שנקלטו — platform', () => {
  test('רשימת המכרזים נטענת עם העמודות מכרז, חברה, מקור, מצב, פירוט #662546 @desktop @prod-safe', async () => {
    // ADT-01 — דרישות 1, 4
    await openTenders(page);
    const ch = page.getByRole('columnheader');
    for (const h of ['מכרז', 'חברה', 'מקור', 'מצב', 'פירוט']) await expect(ch.filter({ hasText: new RegExp(`^${h}$`) }), `колонка «${h}»`).toHaveCount(1);
    expect(await tendersRows(page).count()).toBeGreaterThan(0);
    // в каждой строке есть ссылка «פרטי מכרז» и ячейка источника не пустая
    const rows = tendersRows(page);
    const n = await rows.count();
    await expect(rows.filter({ has: page.getByRole('link', { name: 'פרטי מכרז', exact: true }) })).toHaveCount(n);
    await expect(tendersSearch(page)).toBeVisible();
    await expect(stateFilter(page)).toBeVisible();
  });

  test('סינון לפי מצב קליטה: האפשרויות, ובכל שורה מוצג רק המצב שנבחר #662546 @desktop @prod-safe', async () => {
    // ADT-02 — דרישה 8
    await openTenders(page);
    const total = await tendersRows(page).count();
    const options = await stateFilter(page).locator('option').allInnerTexts();
    expect(options.map((o) => o.trim())).toEqual(['כל המצבים', 'כשל בקליטה', 'כשל בניתוח', 'ממתין לניתוח', 'תקין']);
    await stateFilter(page).selectOption({ label: 'תקין' });
    await expect(async () => {
      const c = await tendersRows(page).count();
      expect(c).toBeGreaterThan(0);
      expect(c).toBeLessThanOrEqual(total);
      await expect(tendersRows(page).filter({ hasText: 'תקין' })).toHaveCount(c);
    }).toPass();
    await expect(tendersRows(page).filter({ hasText: OK_TENDER.title })).toHaveCount(1);
    await stateFilter(page).selectOption({ label: 'ממתין לניתוח' });
    await expect(async () => {
      const c = await tendersRows(page).count();
      expect(c).toBeGreaterThan(0);
      await expect(tendersRows(page).filter({ hasText: 'ממתין לניתוח' })).toHaveCount(c);
    }).toPass();
    await stateFilter(page).selectOption({ label: 'כל המצבים' });
    await expect(tendersRows(page)).toHaveCount(total);
  });

  test('חיפוש לפי שם מכרז או חברה מצמצם את הרשימה #662546 @desktop @prod-safe', async () => {
    // ADT-03 — חיפוש
    await openTenders(page);
    const total = await tendersRows(page).count();
    await tendersSearch(page).fill(OK_TENDER.title);
    await expect(tendersRows(page).filter({ hasText: OK_TENDER.title })).toHaveCount(1);
    await expect(async () => {
      const c = await tendersRows(page).count();
      expect(c).toBeGreaterThanOrEqual(1);
      expect(c).toBeLessThan(total);
      await expect(tendersRows(page).filter({ hasText: OK_TENDER.title })).toHaveCount(c);
    }).toPass();
    await tendersSearch(page).fill('');
    await expect(tendersRows(page)).toHaveCount(total);
    await tendersSearch(page).fill(OK_TENDER.company);
    await expect(async () => {
      const c = await tendersRows(page).count();
      expect(c).toBeGreaterThanOrEqual(1);
      await expect(tendersRows(page).filter({ hasText: OK_TENDER.company })).toHaveCount(c);
    }).toPass();
  });

  test('«פרטי מכרז» בשורה פותח /admin/tenders/<id> (לא /admin), הרענון נשאר בדף, ובדף כל שדות הקליטה #662546 @desktop @prod-safe', async () => {
    // ADT-04 — דרישה 10
    await openTenders(page);
    await tendersSearch(page).fill(OK_TENDER.title);
    const row = tendersRows(page).filter({ hasText: OK_TENDER.title });
    await expect(row).toHaveCount(1);
    await detailsLink(row).click();
    await expectDetailsPage(page, OK_TENDER.id);
    await expect(page).not.toHaveURL(/\/admin$/);
    await expect(page.getByText(OK_TENDER.title, { exact: true }).first()).toBeVisible();
    await expect(page.getByText(OK_TENDER.company, { exact: true }).first()).toBeVisible();
    await expect(page.getByText('העלאה ידנית', { exact: true }).first()).toBeVisible();
    await expect(page.getByText('תקין', { exact: true }).first()).toBeVisible();
    // F5 — נשארים באותו עמוד
    await page.reload();
    await expectDetailsPage(page, OK_TENDER.id);
    // חזרה לרשימה
    await page.getByRole('link', { name: 'חזרה למכרזים שנקלטו' }).click();
    await expect(page).toHaveURL(/\/admin\/tenders$/);
    await expect(page.getByRole('heading', { name: 'ניהול מכרזים שנקלטו', level: 1 })).toBeVisible();
  });

  test('כניסה ישירה של מנהל מערכת ל-/tenders/<id>/analysis מנותבת לדף פרטי המכרז באדמין #662546 @desktop @prod-safe', async () => {
    // ADT-05 — דרישה 10 (כניסה ישירה)
    await page.goto(`/tenders/${OK_TENDER.id}/analysis`);
    await expectDetailsPage(page, OK_TENDER.id);
  });

  test('«לטיפול» פותח חלון טיפול ו«מעבר לפרטי המכרז» מוביל ל-/admin/tenders/<id> (מדלג אם אין מכרז בכשל) #662546 @desktop @prod-safe', async () => {
    // ADT-06 — דרישות 9, 10. «ניסיון חוזר» לא נלחץ לעולם.
    await openTenders(page);
    const treat = page.getByRole('button', { name: 'לטיפול', exact: true });
    test.skip((await treat.count()) === 0, 'אין כרגע מכרז במצב כשל (QA-T2/QA-T3 הוחזרו ל«ממתין») — אין שורת «לטיפול»; הבדיקה נדלגה, לא נכשלה');
    await treat.first().click();
    const dlg = page.getByRole('dialog').or(page.getByRole('alertdialog')).first();
    await expect(dlg).toBeVisible();
    await expect(dlg.getByText(/^טיפול במכרז/)).toBeVisible();
    await dlg.getByRole('link', { name: 'מעבר לפרטי המכרז' }).or(dlg.getByRole('button', { name: 'מעבר לפרטי המכרז' })).first().click();
    await expect(page).toHaveURL(/\/admin\/tenders\/[0-9a-f-]{36}$/);
    await expect(page.getByText('פרטי מכרז שנקלט', { exact: true })).toBeVisible();
    await expect(page.getByRole('link', { name: 'חזרה למכרזים שנקלטו' })).toBeVisible();
  });

  test('המסך לא שינה שום נתון בשרת #662546 @desktop @prod-safe', async () => {
    // ADT-01..06 — только чтение
    expect(mutations, 'экран и детали — только чтение, никаких POST/PATCH/DELETE (кроме входа)').toEqual([]);
  });
});
